CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('master','store_admin')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stores (id uuid PRIMARY KEY, name text NOT NULL, slug text NOT NULL UNIQUE, origin text NOT NULL UNIQUE, api_key text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_members (store_id uuid NOT NULL REFERENCES stores(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (store_id,user_id));
CREATE TABLE IF NOT EXISTS categories (id uuid PRIMARY KEY, store_id uuid NOT NULL REFERENCES stores(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', image_url text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY, store_id uuid NOT NULL REFERENCES stores(id) ON DELETE CASCADE, category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, name text NOT NULL, description text NOT NULL DEFAULT '', details_html text NOT NULL DEFAULT '', price numeric(14,2) NOT NULL CHECK (price >= 0), previous_price numeric(14,2), image_url text NOT NULL DEFAULT '', gallery jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, available boolean NOT NULL DEFAULT true, featured boolean NOT NULL DEFAULT false, badge text NOT NULL DEFAULT '', sku text NOT NULL DEFAULT '', stock integer, fallback text NOT NULL DEFAULT '🛍️', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE products ADD COLUMN IF NOT EXISTS details_html text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS store_settings (store_id uuid PRIMARY KEY REFERENCES stores(id) ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS categories_store_order_idx ON categories(store_id, sort_order);
CREATE INDEX IF NOT EXISTS products_store_active_order_idx ON products(store_id, active, sort_order);
CREATE INDEX IF NOT EXISTS store_members_user_idx ON store_members(user_id);
